<style scoped lang="scss" src="./toggle-switch.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";

@Component
export default class ToggleSwitch extends Vue {
  @Prop({
    type: Boolean,
    default: false
  })
  value;

  currentValue = false;

  mounted() {
    this.currentValue = this.value;
  }

  handleClick() {
    this.currentValue = !this.currentValue;
    this.$forceUpdate();

    /**
     * Emits when the user click the switch button
     *
     * @event switch
     */
    this.$emit("switch", this.currentValue);
  }

  get stateClass() {
    return this.currentValue ? "ToggleSwitch--on" : "ToggleSwitch--off";
  }

  get headStateClass() {
    return this.currentValue ? "ToggleSwitch--headon" : "ToggleSwitch--headoff";
  }
}
</script>

<template>
  <div :class="['ToggleSwitch', stateClass]" @click="handleClick">
    <div :class="['ToggleSwitch__Head', headStateClass]"></div>
  </div>
</template>
